import { regions, statuses } from './columns'
import type { Order } from './columns'

// Fixed "today" so date presets give the same result on server and client.
export const today = new Date('2026-09-23T00:00:00Z')

const customers = [
  'Ava Thompson',
  'Liam Chen',
  'Sofia Patel',
  'Noah Garcia',
  'Mia Johnson',
  'Ethan Kim',
  'Isabella Rossi',
  'Lucas Martin',
  'Amelia Novak',
  'Mason Lee',
]

// Small deterministic PRNG, so the demo data never changes between renders.
function mulberry32(seed: number) {
  return () => {
    seed = (seed + 0x6d2b79f5) | 0
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

const random = mulberry32(42)
const pick = <T>(items: readonly T[]) =>
  items[Math.floor(random() * items.length)]

export const orders: Order[] = Array.from({ length: 30 }, (_, i) => {
  const daysAgo = Math.floor(random() * 120)
  const date = new Date(today.getTime() - daysAgo * 86_400_000)
  return {
    id: `ORD-${String(1001 + i)}`,
    customer: pick(customers),
    region: pick(regions),
    status: pick(statuses),
    date: date.toISOString().slice(0, 10),
    amount: Math.round((20 + random() * 980) * 100) / 100,
  }
}).sort((a, b) => b.date.localeCompare(a.date))

export function toCsv(headers: string[], rows: string[][]): string {
  const escape = (value: string) =>
    /[",\n]/.test(value) ? `"${value.replace(/"/g, '""')}"` : value

  return [headers, ...rows].map((row) => row.map(escape).join(',')).join('\n')
}

export function toExcelHtml(headers: string[], rows: string[][]): string {
  const th = headers.map((h) => `<th>${h}</th>`).join('')
  const trs = rows
    .map((row) => `<tr>${row.map((cell) => `<td>${cell}</td>`).join('')}</tr>`)
    .join('')

  return `<table><thead><tr>${th}</tr></thead><tbody>${trs}</tbody></table>`
}

export function downloadFile(
  content: string,
  filename: string,
  mimeType: string,
) {
  const blob = new Blob([content], { type: mimeType })
  const url = URL.createObjectURL(blob)
  const link = document.createElement('a')
  link.href = url
  link.download = filename
  link.click()
  URL.revokeObjectURL(url)
}

import { regions, statuses } from './columns'
import type { Order } from './columns'

export const datePresets = {
  all: { label: 'Any time', days: null },
  '7d': { label: 'Last 7 days', days: 7 },
  '30d': { label: 'Last 30 days', days: 30 },
  '90d': { label: 'Last 90 days', days: 90 },
} as const

export type DatePreset = keyof typeof datePresets
export type ExportFormat = 'csv' | 'excel'

export type ExportConfig = {
  statuses: Order['status'][]
  regions: Order['region'][]
  datePreset: DatePreset
  columns: string[]
  format: ExportFormat
}

export function defaultExportConfig(columnIds: string[]): ExportConfig {
  return {
    statuses: [...statuses],
    regions: [...regions],
    datePreset: 'all',
    columns: columnIds,
    format: 'csv',
  }
}

// One function decides which rows are exported. The dialog's live count and
// the downloaded file both call it, so they can't disagree.
export function applyExportConfig(
  rows: Order[],
  config: ExportConfig,
  today: Date,
): Order[] {
  const days = datePresets[config.datePreset].days
  const from =
    days === null
      ? null
      : new Date(today.getTime() - days * 86_400_000).toISOString().slice(0, 10)

  return rows.filter(
    (row) =>
      config.statuses.includes(row.status) &&
      config.regions.includes(row.region) &&
      (from === null || row.date >= from),
  )
}

'use client'

import { useId } from 'react'
import { Download } from 'lucide-react'

import { Button } from '#/components/ui/button'
import { Checkbox } from '#/components/ui/checkbox'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '#/components/ui/dialog'
import { Label } from '#/components/ui/label'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '#/components/ui/select'
import { cn } from '#/lib/utils.ts'
import { regions, statuses } from './columns'
import { datePresets } from './export-config'
import type { DatePreset, ExportConfig, ExportFormat } from './export-config'

function toggle<T>(list: T[], value: T): T[] {
  return list.includes(value)
    ? list.filter((item) => item !== value)
    : [...list, value]
}

function CheckboxGroup<T extends string>({
  label,
  options,
  selected,
  onChange,
  getLabel = (value) => value,
}: {
  label: string
  options: readonly T[]
  selected: T[]
  onChange: (next: T[]) => void
  getLabel?: (value: T) => string
}) {
  const id = useId()
  return (
    <fieldset className="space-y-2">
      <legend className="text-sm font-medium">{label}</legend>
      <div className="flex flex-wrap gap-2">
        {options.map((option) => {
          const checked = selected.includes(option)
          return (
            <Label
              key={option}
              htmlFor={`${id}-${option}`}
              className={cn(
                'flex cursor-pointer items-center gap-2 rounded-md border px-2.5 py-1.5 text-sm font-normal transition-colors',
                checked
                  ? 'border-foreground/25 bg-muted/60'
                  : 'text-muted-foreground',
              )}
            >
              <Checkbox
                id={`${id}-${option}`}
                checked={checked}
                onCheckedChange={() => onChange(toggle(selected, option))}
              />
              {getLabel(option)}
            </Label>
          )
        })}
      </div>
    </fieldset>
  )
}

interface ExportDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  columns: { id: string; label: string }[]
  config: ExportConfig
  onConfigChange: (config: ExportConfig) => void
  onReset: () => void
  onExport: () => void
  matchCount: number
  total: number
}

export function ExportDialog({
  open,
  onOpenChange,
  columns,
  config,
  onConfigChange,
  onReset,
  onExport,
  matchCount,
  total,
}: ExportDialogProps) {
  const set = <TKey extends keyof ExportConfig>(
    key: TKey,
    value: ExportConfig[TKey],
  ) => onConfigChange({ ...config, [key]: value })

  const labels = Object.fromEntries(columns.map((c) => [c.id, c.label]))
  const canExport = matchCount > 0 && config.columns.length > 0

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-lg">
        <DialogHeader>
          <DialogTitle>Export orders</DialogTitle>
          <DialogDescription>
            Choose which orders and columns to include. The table itself stays
            unfiltered.
          </DialogDescription>
        </DialogHeader>

        <div className="max-h-[60svh] space-y-5 overflow-y-auto py-1">
          <CheckboxGroup
            label="Status"
            options={statuses}
            selected={config.statuses}
            onChange={(next) => set('statuses', next)}
          />
          <CheckboxGroup
            label="Region"
            options={regions}
            selected={config.regions}
            onChange={(next) => set('regions', next)}
          />

          <div className="space-y-2">
            <p className="text-sm font-medium">Date</p>
            <Select
              value={config.datePreset}
              onValueChange={(value) => set('datePreset', value as DatePreset)}
            >
              <SelectTrigger className="w-44" aria-label="Date range">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {Object.entries(datePresets).map(([value, preset]) => (
                  <SelectItem key={value} value={value}>
                    {preset.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <CheckboxGroup
            label="Columns"
            options={columns.map((c) => c.id)}
            selected={config.columns}
            onChange={(next) =>
              // Keep the table's column order, whatever order they were ticked in
              set(
                'columns',
                columns.map((c) => c.id).filter((id) => next.includes(id)),
              )
            }
            getLabel={(id) => labels[id] ?? id}
          />

          <fieldset className="space-y-2">
            <legend className="text-sm font-medium">Format</legend>
            <div className="inline-flex rounded-md border p-0.5">
              {(['csv', 'excel'] as ExportFormat[]).map((format) => (
                <button
                  key={format}
                  type="button"
                  aria-pressed={config.format === format}
                  onClick={() => set('format', format)}
                  className={cn(
                    'rounded-sm px-3 py-1 text-sm transition-colors',
                    config.format === format
                      ? 'bg-muted text-foreground'
                      : 'text-muted-foreground hover:text-foreground',
                  )}
                >
                  {format === 'csv' ? 'CSV' : 'Excel'}
                </button>
              ))}
            </div>
          </fieldset>
        </div>

        <DialogFooter className="items-center gap-2 sm:justify-between">
          <p className="text-sm text-muted-foreground" aria-live="polite">
            <span className="font-medium text-foreground tabular-nums">
              {matchCount} of {total}
            </span>{' '}
            rows will be exported
          </p>
          <div className="flex gap-2">
            <Button type="button" variant="ghost" onClick={onReset}>
              Reset
            </Button>
            <Button
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
            >
              Cancel
            </Button>
            <Button type="button" disabled={!canExport} onClick={onExport}>
              <Download className="size-3.5" />
              Export
            </Button>
          </div>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

'use client'

import { useMemo, useState } from 'react'
import {
  flexRender,
  getCoreRowModel,
  getPaginationRowModel,
  useReactTable,
} from '@tanstack/react-table'
import type { ColumnDef } from '@tanstack/react-table'
import { ChevronLeft, ChevronRight, Download } from 'lucide-react'

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '#/components/ui/table'
import { Button } from '#/components/ui/button'
import type { Order } from './columns'
import { applyExportConfig, defaultExportConfig } from './export-config'
import type { ExportConfig } from './export-config'
import { ExportDialog } from './export-dialog'
import { downloadFile, toCsv, toExcelHtml } from './export'

interface ExportConfigTableProps {
  columns: ColumnDef<Order, any>[]
  data: Order[]
  today: Date
}

export function ExportConfigTable({
  columns,
  data,
  today,
}: ExportConfigTableProps) {
  const table = useReactTable({
    data,
    columns,
    getCoreRowModel: getCoreRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    initialState: { pagination: { pageSize: 8 } },
  })

  // The column list for the dialog comes from the table, not a second list
  const exportColumns = useMemo(
    () =>
      table.getAllLeafColumns().map((column) => ({
        id: column.id,
        label:
          typeof column.columnDef.header === 'string'
            ? column.columnDef.header
            : column.id,
      })),
    [table],
  )

  const [open, setOpen] = useState(false)
  const [config, setConfig] = useState<ExportConfig>(() =>
    defaultExportConfig(exportColumns.map((c) => c.id)),
  )

  const matches = useMemo(
    () => applyExportConfig(data, config, today),
    [data, config, today],
  )

  function handleExport() {
    const chosen = exportColumns.filter((c) => config.columns.includes(c.id))
    const headers = chosen.map((c) => c.label)
    // Export raw values (e.g. 129.5, not "$129.50") so spreadsheets can sum them
    const rows = matches.map((order) =>
      chosen.map((c) => String(order[c.id as keyof Order])),
    )

    if (config.format === 'csv') {
      downloadFile(
        toCsv(headers, rows),
        'orders.csv',
        'text/csv;charset=utf-8;',
      )
    } else {
      downloadFile(
        toExcelHtml(headers, rows),
        'orders.xls',
        'application/vnd.ms-excel',
      )
    }
    setOpen(false)
  }

  const { pageIndex, pageSize } = table.getState().pagination

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between gap-3">
        <p className="text-sm text-muted-foreground">{data.length} orders</p>
        <Button
          type="button"
          variant="outline"
          size="sm"
          onClick={() => setOpen(true)}
        >
          <Download className="size-3.5" />
          Export…
        </Button>
      </div>

      <div className="overflow-hidden rounded-md border">
        <Table>
          <TableHeader>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id}>
                {headerGroup.headers.map((header) => (
                  <TableHead key={header.id}>
                    {flexRender(
                      header.column.columnDef.header,
                      header.getContext(),
                    )}
                  </TableHead>
                ))}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows.map((row) => (
              <TableRow key={row.id}>
                {row.getVisibleCells().map((cell) => (
                  <TableCell key={cell.id}>
                    {flexRender(cell.column.columnDef.cell, cell.getContext())}
                  </TableCell>
                ))}
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </div>

      <div className="flex items-center justify-end gap-2">
        <p className="mr-auto text-sm text-muted-foreground tabular-nums">
          {pageIndex * pageSize + 1}–
          {Math.min((pageIndex + 1) * pageSize, data.length)} of {data.length}
        </p>
        <Button
          type="button"
          variant="outline"
          size="icon"
          className="size-8"
          aria-label="Previous page"
          onClick={() => table.previousPage()}
          disabled={!table.getCanPreviousPage()}
        >
          <ChevronLeft className="size-4" />
        </Button>
        <Button
          type="button"
          variant="outline"
          size="icon"
          className="size-8"
          aria-label="Next page"
          onClick={() => table.nextPage()}
          disabled={!table.getCanNextPage()}
        >
          <ChevronRight className="size-4" />
        </Button>
      </div>

      <ExportDialog
        open={open}
        onOpenChange={setOpen}
        columns={exportColumns}
        config={config}
        onConfigChange={setConfig}
        onReset={() =>
          setConfig(defaultExportConfig(exportColumns.map((c) => c.id)))
        }
        onExport={handleExport}
        matchCount={matches.length}
        total={data.length}
      />
    </div>
  )
}

import { columns } from './columns'
import { ExportConfigTable } from './data-table'
import { orders, today } from './data'

export function ExportConfigDemo() {
  return <ExportConfigTable columns={columns} data={orders} today={today} />
}
